from fractions import Fraction
from itertools import combinations

def height(q: Fraction) -> int:
    q = Fraction(q)
    return abs(q.numerator) + q.denominator

def vp(n: int, p: int) -> int:
    n = abs(n); v = 0
    while n and n % p == 0:
        n //= p; v += 1
    return v

def pabs(q: Fraction, p: int) -> Fraction:
    q = Fraction(q)
    if q == 0:
        return Fraction(0)
    return Fraction(p) ** (-(vp(q.numerator, p) - vp(q.denominator, p)))

def height_dist(x: Fraction, y: Fraction) -> int:
    return height(x - y)

def padic_dist(x: Fraction, y: Fraction, p: int) -> Fraction:
    return pabs(x - y, p)

def strong_triangle_ok(d, x, y, z) -> bool:
    return d(x, z) <= max(d(x, y), d(y, z))

def main() -> None:
    p = 2
    pts = [Fraction(a, b) for a in range(-6, 7) for b in (1, 2, 3)]
    h_fail = h_tot = u_fail = u_tot = 0
    for x, y, z in combinations(pts, 3):
        h_tot += 1
        if not strong_triangle_ok(lambda a, b: height_dist(a, b), x, y, z):
            h_fail += 1
        u_tot += 1
        if not strong_triangle_ok(lambda a, b: padic_dist(a, b, p), x, y, z):
            u_fail += 1
    print(f'height distance: {h_fail}/{h_tot} triples VIOLATE strong triangle law')
    print(f'p-adic distance: {u_fail}/{u_tot} triples violate strong triangle law')

if __name__ == '__main__':
    main()

